import{z as n,x as i,o as E,c as B,q as s,j as t,D as e,d as r,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"输出后处理管线","description":"","frontmatter":{"title":"输出后处理管线","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-postprocess-pipeline.md","filePath":"llm/dec-postprocess-pipeline.md","lastUpdated":1791413859000}'),p={name:"llm/dec-postprocess-pipeline.md"};function d(c,a,m,h,C,F){const o=i("Mermaid");return E(),B("div",null,[a[2]||(a[2]=s('<h1 id="输出后处理管线" tabindex="-1">输出后处理管线 <a class="header-anchor" href="#输出后处理管线" aria-label="Permalink to &quot;输出后处理管线&quot;">​</a></h1><div class="epigraph"><p>后处理的每一刀都要留底：改过的文本不再是模型的输出，回填历史、写日志、交付客户端，三处必须用同一份决定。</p><footer>—— 据 OpenAI 兼容接口的输出约定与 JSON Schema 校验器实践整理</footer></div><p><a href="/llm/dec-stream-reparse">上一课</a>把 token 流变成事件流交出去。本课管最后一公里：解码完成后的<strong>后处理</strong>。零件分散在基础课里：stop 命中后的裁剪在 <a href="/llm/stop-sequences">stop 课</a>，schema 校验与回退在 <a href="/llm/json-constrained-decode">JSON 约束课</a>，工具片段的切分在 <a href="/llm/function-calling">function calling</a>。本课把它们排成一条有序管线，钉住每一步的输入输出不变量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一段生成文本从解码器出来，到成为交付物，要过若干刀：裁掉 stop 命中段及其右侧、剥离围栏与角色残片、规范化 unicode 与空白、schema 或正则校验、失败时修复或重试、脱敏与内容过滤、包装（加引用、加代码围栏）。这些步骤散落在网关、SDK 与业务代码里时，同一请求在不同客户端得到不同文本；更要命的是<strong>回填历史用哪份文本</strong>没有定论——模型下一轮见到的上下文与它上一轮实际生成的对不上，是又一处条件前缀 OOD。缺口是把后处理当系统对象：顺序、幂等、留痕、与解码层的关系。</p><p><span class="marginnote">术语翻译：「回填历史」就是把模型这轮说的话存进对话记录，让它在下一轮还能「看见」。为什么必须用同一份文本——如果给用户看的是裁剪过的，存进历史的却是带 stop 残段的原始版，模型下一轮会以为自己说过那些多余的话，越聊越跑偏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>固定阶段序</strong>，每阶段声明不变量：</p><ol><li><strong>裁剪</strong>：stop 与 eos 命中段的右侧切除；多模式按最长匹配优先（<a href="/llm/stop-sequences">stop 课</a>钉过）。不变量：输出是模型生成文本的真前缀。</li><li><strong>规范化</strong>：unicode 形式、行尾、空白折叠。不变量：可逆或有留痕——规范化改变字节，回填与日志必须用同一份。</li><li><strong>校验</strong>：schema <code>fullmatch</code> 断言（<a href="/llm/regex-constrained-decode">正则课</a>的老规矩）。失败分两路：解码层回退（空支撑集）与内容越界（事实、取值），处理不同。</li><li><strong>修复</strong>：JSON repair 是启发式，修复后的对象不再等于模型输出。日志存双份（原始与修复后），修复率是解码质量的观测指标。</li><li><strong>脱敏与过滤</strong>：PII、内容分类，独立于 stop 的通道。</li><li><strong>包装</strong>：加围栏、注入引用，只在交付面生效，不进历史。</li></ol>',9)),(E(),t(A,null,{default:e(()=>[l(o,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%E5%8E%9F%E5%A7%8B%E6%96%87%E6%9C%AC%22%5D%20--%3E%20CUT%5B%22%E8%A3%81%E5%89%AA%EF%BC%9Astop%20%2F%20eos%20%E5%8F%B3%E4%BE%A7%22%5D%0A%20%20CUT%20--%3E%20NORM%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%EF%BC%9Aunicode%20%2F%20%E7%A9%BA%E7%99%BD%22%5D%0A%20%20NORM%20--%3E%20VAL%7B%22schema%20%2F%20%E6%AD%A3%E5%88%99%E6%96%AD%E8%A8%80%22%7D%0A%20%20VAL%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20SAFE%5B%22%E8%84%B1%E6%95%8F%E4%B8%8E%E8%BF%87%E6%BB%A4%22%5D%0A%20%20VAL%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20REP%7B%22%E4%BF%AE%E5%A4%8D%20or%20%E9%87%8D%E8%AF%95%22%7D%0A%20%20REP%20--%3E%7C%E4%BF%AE%E5%A4%8D%7C%20SAFE%0A%20%20REP%20--%3E%7C%E9%87%8D%E8%AF%95%7C%20RAW%0A%20%20SAFE%20--%3E%20WRAP%5B%22%E5%8C%85%E8%A3%85%EF%BC%9A%E5%9B%B4%E6%A0%8F%20%2F%20%E5%BC%95%E7%94%A8%EF%BC%88%E4%BB%85%E4%BA%A4%E4%BB%98%E9%9D%A2%EF%BC%89%22%5D%0A%20%20WRAP%20--%3E%20OUT%5B%22%E4%BA%A4%E4%BB%98%20%2B%20%E5%8E%86%E5%8F%B2%E5%9B%9E%E5%A1%AB%20%2B%20%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h3 id="一致性三角" tabindex="-1">一致性三角 <a class="header-anchor" href="#一致性三角" aria-label="Permalink to &quot;一致性三角&quot;">​</a></h3><p>三份文本必须对齐：<strong>交付文本</strong>（用户看到的）、<strong>历史文本</strong>（回填进下一轮上下文的）、<strong>日志文本</strong>（复盘用的）。包装层只影响交付面；历史回填用裁剪加规范化后的文本；日志存原始文本与每阶段的变更记录。三处各用各的，是复盘失真与 OOD 的共同根源。</p><p><span class="marginnote">常见误区：初学者容易以为「修复器好使就行」。实际上 JSON repair 常用的操作——补引号、删尾逗号、关括号——会把模型的输出改得面目全非。修复率 5% 意味着每 20 条回复里就有 1 条不是模型真正说的；这 5% 是解码层配置漂移的警报，把它修「好」等于拆掉警报器。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>管线的正确性论证在不变量上：裁剪保证「交付的是模型说过的」，因此历史回填不引入模型没见过的形态；校验保证「进下游的是契约允许的」；修复是唯一会伪造模型输出的阶段，所以必须留底并单独计量。修复率是金丝雀：它突然升高，先查引擎、分词器或文法配置是否变化，而不是庆祝修复器好用——修复器掩盖的正是解码层配置的漂移。</p><p>与解码层的分工：掩码层的失败（空支撑集回退、降级路径）必须在管线里可见，标记到请求元数据；管线不静默吞掉解码层的事故，否则「总有输出」的表象会掩盖类型契约已经破裂的事实（<a href="/llm/json-schema-decode">JSON Schema 课</a>的老边界）。</p><p>第一张图画的是阶段的先后；一致性三角回答的是另一个问题——各阶段的结果分别流向三份文本中的哪一份：</p>',7)),(E(),t(A,null,{default:e(()=>[l(o,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20LR%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E8%A7%A3%E7%A0%81%E6%96%87%E6%9C%AC%22%5D%20--%3E%20CUT%5B%22%E8%A3%81%E5%89%AA%22%5D%0A%20%20CUT%20--%3E%20NORM%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20VAL%5B%22%E6%A0%A1%E9%AA%8C%2F%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20NORM%20--%3E%20HIST%5B%22%E5%8E%86%E5%8F%B2%E6%96%87%E6%9C%AC%3Cbr%2F%3E%EF%BC%88%E5%9B%9E%E5%A1%AB%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%89%22%5D%0A%20%20VAL%20--%3E%20SAFE%5B%22%E8%84%B1%E6%95%8F%2F%E8%BF%87%E6%BB%A4%22%5D%20--%3E%20WRAP%5B%22%E5%8C%85%E8%A3%85%EF%BC%9A%E5%9B%B4%E6%A0%8F%2F%E5%BC%95%E7%94%A8%22%5D%20--%3E%20DELIV%5B%22%E4%BA%A4%E4%BB%98%E6%96%87%E6%9C%AC%3Cbr%2F%3E%EF%BC%88%E7%94%A8%E6%88%B7%E7%9C%8B%E5%88%B0%EF%BC%89%22%5D%0A%20%20RAW%20--%3E%20LOG%5B%22%E6%97%A5%E5%BF%97%E6%96%87%E6%9C%AC%3Cbr%2F%3E%EF%BC%88%E5%8E%9F%E5%A7%8B%20%2B%20%E5%8F%98%E6%9B%B4%E7%95%99%E7%97%95%EF%BC%89%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">为什么重要：这三条去向如果各写各的代码，同一请求在 App、网页、日志里就是三个版本。复盘事故时对着日志看，永远复现不出用户看到的现象——因为日志里那份文本从来没被任何人「看到」过。对齐规则要写成一份共享实现，不是三处约定。</span></p><p><span class="marginnote">重试的经济学：修复是毫秒级、重试是秒级。管线应先修复再重试，且重试必须携带失败原因——「校验失败加错误信息再生成」是 <a href="/llm/json-schema-decode">JSON Schema 课</a>的第一条解码路径，重试不声明原因等于让模型盲猜。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>后处理不能创造质量：它裁剪、规范化、验证、包装，不能把错答案改对——语义层的对错归验证器与重采样（<a href="/llm/best-of-n">Best-of-N</a>）。安全过滤放在管线哪一段是产品决策：早过滤省下游计算，晚过滤少误杀上下文；但无论放哪，被滤内容都不回填历史。流式场景下管线要能跑增量（裁剪与脱敏在事件层之前的部分必须流式友好），整段校验仍在闭合后——流式与后处理的关系归流式课，本课钉的是完成后的段。下一课把候选从一条放大到 \\(N\\) 条：best-of-n 的服务化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固定阶段序：裁剪 → 规范化 → 校验 → 修复 → 脱敏 → 包装，每阶段声明不变量。</li><li>一致性三角：交付、历史、日志三份文本的对齐规则必须写死，包装不进历史。</li><li>修复是唯一伪造模型输出的阶段：存双份、计量修复率，修复率突变先查解码层。</li><li>解码层事故（回退、降级）要在管线元数据可见，不静默吞掉。</li><li>重试先修复后重试，重试携带失败原因与上下文。</li><li>出处：据开放 API 输出约定与 JSON Schema 校验器实践整理；裁剪与校验语义见 stop sequences、JSON 约束、正则约束各课。</li></ul>',6))])}const g=n(p,[["render",d]]);export{f as __pageData,g as default};
